% smooth cycle through scattered points
\draw[thick, blue!60!black, fill=blue!8]
  plot[smooth cycle, tension=0.7] coordinates {(0,0) (1.6,0.9) (3.1,0.2) (2.6,-1.5) (0.9,-1.9)};
\node[font=\tiny, blue!60!black] at (1.6,-0.5) {smooth cycle};
% to[out=..,in=..] chains
\node[draw, circle, minimum size=7mm] (x) at (5.5,0) {x};
\node[draw, circle, minimum size=7mm] (y) at (8.5,0) {y};
\draw[-{Stealth[length=3mm,width=2mm]}] (x) to[out=60,in=120] (y);
\draw[-{Latex[length=2mm]}]             (x) to[out=-60,in=-120] (y);
\draw[{Circle[open]}-{Diamond[length=2.5mm]}] (x) to[out=20,in=160] (y);
% label= and pin= chain on one node
\node[draw, fill=orange!25, minimum size=9mm,
      label={above:label above}, label={below:label below},
      label={[red]left:red left}, pin={[pin distance=8mm]30:pinned}] (z) at (5.5,-3) {z};
% nested pgfmathparse
\pgfmathparse{max(min(3,7), abs(-2)) + veclen(3,4)/5}
\node[font=\small] at (9,-3) {nested parse = \pgfmathresult};
\pgfmathparse{int(round(sqrt(144)))}
\node[font=\small] at (9,-3.6) {int(round(sqrt(144))) = \pgfmathresult};
